using System;
using System.Linq;
using System.Collections.Generic;
using NUnit.Framework;
using UnityEngine;
using UnityEditor.SceneManagement;
using SporeGobbo.Geometry.Preview.Editor;
namespace SporeGobbo.Geometry.Preview.Tests
{
 public sealed class Stage54Tests
 {
  static ExplorationFixture fixture;static DiscoveryIndex index;
  [OneTimeSetUp]public void Setup(){fixture=new ExplorationFixture();index=new DiscoveryIndex(new StreamingWorld(1024,1024,47045,fixture),fixture.Regions);}
  [Test]public void PaletteExactlyMatchesAllTwentyNamedSrgbBaselines(){var p=ScriptableObject.CreateInstance<Stage54Palette>();Assert.That(p.entries.Length,Is.EqualTo(20));Assert.That(p.entries.Select(e=>e.name).Distinct().Count(),Is.EqualTo(20));Assert.That(p.entries[0].hex,Is.EqualTo("#08120F"));Assert.That(p.entries[4].hex,Is.EqualTo("#987052"));foreach(var e in p.entries)Assert.That(ColorUtility.ToHtmlStringRGB(p.Color(e.name)),Is.EqualTo(e.hex.Substring(1)));UnityEngine.Object.DestroyImmediate(p);}
  [Test]public void MaterialIdentityDoesNotChangeProtectedAuthority(){var w=new StreamingWorld(1024,1024,47045,fixture);Assert.That(fixture.Materials,Does.Contain(PreviewMatter.Stone));Assert.That(fixture.Materials,Does.Contain(PreviewMatter.Bone));Assert.That(fixture.Materials,Does.Contain(PreviewMatter.Root));foreach(var l in fixture.Landmarks)foreach(var c in l.Footprint){Assert.That(w.IsSolid(c.X,c.Y));Assert.That(w.Excavate(c.X,c.Y),Is.False);}}
  [Test]public void InitialMemoryIsOnlyComfortableChamberNotWholeNetwork(){Assert.That(fixture.InitialKnown.Count,Is.InRange(500,1200));Assert.That(index.CellCount,Is.GreaterThan(fixture.InitialKnown.Count*10));using(var e=new ExplorationExperiment()){Assert.That(e.Discovery.Known(fixture.X+65,fixture.Y-61),Is.False);Assert.That(e.Presentation.IsSolid(fixture.X+65,fixture.Y-61));}}
  [Test]public void IntegratedCircuitHasPhysicalRoutesIncludingWideTurns(){var w=new StreamingWorld(1024,1024,47045,fixture);var route=new List<Point2>();for(int i=1;i<fixture.Tour.Count;i++)Assert.That(new LabNavigation(w,fixture.Tour[i-1]).TraceToRoot(fixture.Tour[i],1,route),"Tour segment "+i);}
  [TestCase(1)][TestCase(3)][TestCase(5)][TestCase(7)][TestCase(9)]public void IrregularRootWideRouteRetainsFootprintClearance(int size){var w=new StreamingWorld(1024,1024,47045,fixture);var route=new List<Point2>();Assert.That(new LabNavigation(w,fixture.P(54,7)).TraceToRoot(fixture.P(54,-17),size,route));foreach(var p in route)Assert.That(PreviewMotion.Fits(w,Stage54Preview.V(p),size));}
  [Test]public void OrganicRootJoinsAndBranchReuseExactExistingEdges(){var root=fixture.Landmarks[1];var a=root.Parts[0].Sections.Last();var b=root.Parts[1].Sections[0];Assert.That(a.Left,Is.EqualTo(b.Right));Assert.That(a.Right,Is.EqualTo(b.Left));var branch=root.Parts[2].Sections[0];Assert.That(branch.Left,Is.EqualTo(root.Parts[1].Sections[12].Left));Assert.That(branch.Right,Is.EqualTo(root.Parts[1].Sections[12].Right));Assert.That(root.Parts[0].Sections[8].Height,Is.Not.EqualTo(root.Parts[0].Sections[24].Height));}
  [Test]public void AssemblyIsDeterministicAndExposedShoulderHasRealWidth(){var f=new ExplorationFixture();foreach(int i in Enumerable.Range(0,fixture.Landmarks.Count))foreach(int j in Enumerable.Range(0,fixture.Landmarks[i].Parts.Length))Assert.That(f.Landmarks[i].Parts[j].Sections.Select(x=>x.Left),Is.EqualTo(fixture.Landmarks[i].Parts[j].Sections.Select(x=>x.Left)));var s=fixture.Landmarks[0].Parts[0].Sections[10];Assert.That(s.Right.X-s.Left.X,Is.GreaterThan(8));}
  [Test]public void ExposedSpikeDoesNotLeakHiddenFloorOrChangeFootprint(){using(var e=new ExplorationExperiment()){var p=fixture.P(18,-38);Assert.That(e.Presentation.IsSolid((int)p.X,(int)p.Y));Assert.That(StructureMesh.GroundVisible(fixture.Landmarks[0],e.Discovery),Is.False);Assert.That(e.Discovery.ContentAllowed(p,p),Is.False);}}
  [Test]public void ExplicitDiscoveryMetadataHasDifferentDurationsAndBoundedNetwork(){Assert.That(index.ById["54/small"].Policy,Is.EqualTo(DiscoveryPolicy.Immediate));Assert.That(index.ById["54/occupied"].RevealSeconds,Is.LessThan(.1));Assert.That(index.ById["54/occupied"].LocalImmediate,Is.EqualTo(12));Assert.That(index.ById["54/large"].RevealSeconds,Is.EqualTo(.3));Assert.That(index.Regions.Where(r=>r.Id.StartsWith("54/hidden-network")).All(r=>r.Policy==DiscoveryPolicy.Bounded&&r.Cells.Length<=256));}
  sealed class OpenDefinition:IStreamingTerrainDefinition{public bool Protected(int x,int y)=>false;public bool TrySolid(int x,int y,out bool solid){solid=false;return true;}}
  [Test]public void LocalThreatReadabilityReleasedImmediatelyWithinBoundedMetadata(){var w=new StreamingWorld(32,32,47045,new OpenDefinition());var cells=new List<int>();for(int y=4;y<=20;y++)for(int x=4;x<=20;x++)cells.Add(y*32+x);var ix=new DiscoveryIndex(w,new[]{new DiscoveryRegion("threat",cells,DiscoveryPolicy.Gradual,.08,12)});using(var d=new CaveDiscovery(w,ix){MaxReleases=16}){d.Explore(new Point2(12.5,12.5));d.Tick(0);Assert.That(d.Shown(12,12));Assert.That(d.Shown(12,18));Assert.That(d.PendingReleases,Is.GreaterThanOrEqualTo(0));Assert.That(d.Remembered.Count,Is.LessThanOrEqualTo(1024));}}
  [Test]public void CanonicalCellEmissionMatchesUnchangedBuilder(){using(var e=new ExplorationExperiment()){var a=new PreviewMeshData("a",PreviewLayer.Solid);PreviewMeshBuilder.EmitCellSolid(e.World,540,508,a);var b=PreviewMeshBuilder.BuildPatch(e.World,new ContourTerrainCache(e.World),540,508,1)[0];Assert.That(a.Vertices,Is.EqualTo(b.Vertices));Assert.That(a.Indices,Is.EqualTo(b.Indices));}}
  [Test]public void TerrainEmergenceClippingIsDeterministicAndDoesNotWriteWorld(){using(var e=new ExplorationExperiment()){var p=fixture.Landmarks[1].Parts[2];var source=new PreviewMeshData("s",PreviewLayer.Gobbo);StructureMesh.Build(p,source);var a=new PreviewMeshData("a",PreviewLayer.Gobbo);var b=new PreviewMeshData("b",PreviewLayer.Gobbo);StructureTerrainClip.Build(source,a,e.World,fixture.Landmarks[1]);StructureTerrainClip.Build(source,b,e.World,fixture.Landmarks[1]);Assert.That(a.Vertices,Is.EqualTo(b.Vertices));Assert.That(e.World.Revision,Is.Zero);Assert.That(a.Vertices.Count,Is.LessThan(source.Vertices.Count*500));}}
  [Test]public void RubbleRefillKeepsRememberedGeography(){using(var e=new ExplorationExperiment()){var c=fixture.Rubble[fixture.Rubble.Count/2];Assert.That(e.World.IsSolid(c.X,c.Y));Assert.That(e.World.Excavate(c.X,c.Y));e.Discovery.Explore(new Point2(c.X+.5,c.Y+.5));e.Discovery.Tick(1);var remembered=new HashSet<int>(e.Discovery.Remembered);Assert.That(e.World.Refill(c.X,c.Y));Assert.That(e.Discovery.Remembered.SetEquals(remembered));}}
  [Test]public void FullRevealRetainsCanonicalTerrainAndCrossChunkAnchors(){using(var e=new ExplorationExperiment()){foreach(var r in e.Index.Regions)e.Discovery.SeedKnown(r.Cells);var a=PreviewMeshBuilder.BuildPatch(e.Presentation,new ContourTerrainCache(e.Presentation),528,480,16);var b=PreviewMeshBuilder.BuildPatch(e.World,new ContourTerrainCache(e.World),528,480,16);for(int i=0;i<4;i++){Assert.That(a[i].Vertices,Is.EqualTo(b[i].Vertices));Assert.That(a[i].Indices,Is.EqualTo(b[i].Indices));}}}
  [Test]public void AllOpenStructuralTrianglesAreNotNeedlesslySubdivided(){var w=new StreamingWorld(32,32,47045,new OpenDefinition());var part=StructuralPrimitives.Spike("test",new Point2(16.5,25.5),4,10);var land=new DimensionalLandmark("test",new DualTile[0],new DualTile[0],new[]{part});var source=new PreviewMeshData("source",PreviewLayer.Gobbo);StructureMesh.Build(part,source);var result=new PreviewMeshData("result",PreviewLayer.Gobbo);StructureTerrainClip.Build(source,result,w,land);Assert.That(result.Indices.Count,Is.EqualTo(source.Indices.Count));Assert.That(Area(result),Is.EqualTo(Area(source)).Within(1e-8));}
  [Test]public void LandmarkBoundsAlsoContainProtectedGroundCells(){foreach(var l in fixture.Landmarks)foreach(var c in l.Footprint){Assert.That(c.X,Is.GreaterThanOrEqualTo(l.Bounds.Min.X));Assert.That(c.Y,Is.GreaterThanOrEqualTo(l.Bounds.Min.Y));Assert.That(c.X+1,Is.LessThanOrEqualTo(l.Bounds.Max.X));Assert.That(c.Y+1,Is.LessThanOrEqualTo(l.Bounds.Max.Y));}}
  [Test]public void RootContactsStartUndiscovered(){using(var e=new ExplorationExperiment()){Assert.That(StructureMesh.GroundVisible(e.Fixture.Landmarks[1],e.Discovery),Is.False);}}
  static double Area(PreviewMeshData d){double area=0;for(int i=0;i<d.Indices.Count;i+=3)area+=Math.Abs(PreviewMeshData.Cross(d.LogicalVertices[d.Indices[i]].Logical,d.LogicalVertices[d.Indices[i+1]].Logical,d.LogicalVertices[d.Indices[i+2]].Logical))*.5;return area;}
  [Test]public void DiggingAroundBuriedBranchExposesMoreAttachedGeometry(){using(var e=new ExplorationExperiment()){var root=e.Fixture.Landmarks[1];var source=new PreviewMeshData("root",PreviewLayer.Gobbo);StructureMesh.Build(root.Parts[2],source);var a=new PreviewMeshData("before",PreviewLayer.Gobbo);var b=new PreviewMeshData("after",PreviewLayer.Gobbo);StructureTerrainClip.Build(source,a,e.World,root);for(int y=-32;y<=-27;y++)for(int x=72;x<=78;x++)e.World.Excavate(e.Fixture.X+x,e.Fixture.Y+y);StructureTerrainClip.Build(source,b,e.World,root);Assert.That(Area(b),Is.GreaterThan(Area(a)));}}
  [Test]public void ResetCleanupAndCameraTopologyAreBounded(){Stage54Tools.Install();var p=UnityEngine.Object.FindAnyObjectByType<Stage54Preview>();p.Initialize();Assert.That(p.Lab.Actors[0].SpawnValid);Assert.That(p.Lab.PresentationAllowed(p.Lab.Actors[0].Position),Is.False);for(int i=0;i<3;i++){p.ResetDemo();Assert.That(p.OwnedMeshes,Is.EqualTo(17));Assert.That(p.GetComponentsInChildren<MeshFilter>().Count(f=>f.name.StartsWith("Stage54 ")),Is.EqualTo(17));}int b=p.StructureBuilds;for(int i=0;i<2;i++){p.anchor=i;p.Live.settings.anchor=Stage54Preview.Anchors[i];p.Live.Refresh(1f/60);}Assert.That(p.StructureBuilds,Is.EqualTo(b));var meshes=p.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("Stage54 ")).Select(f=>f.sharedMesh).ToArray();p.Shutdown();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);Assert.That(meshes.All(m=>m==null));}
 }
}
